fn format_currency_int(n: u64) -> String {
    let s = n.to_string();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    let mut result = String::with_capacity(len + len / 3);
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_currency_avg(avg: f64) -> String {
    let s = format!("{:.2}", avg);
    let dot_pos = s.find('.').unwrap();
    let int_part = &s[..dot_pos];
    let dec_part = &s[dot_pos + 1..];
    let int_formatted = format_currency_int(int_part.parse::<u64>().unwrap_or(0));
    format!("{}.{}", int_formatted, dec_part)
}

