import heapq
import math

def main():
    file_path = "__FIXTURE_DIR__/graph.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        u, v, w = edge["from"], edge["to"], edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = {node: math.inf for node in nodes}
    dist["A"] = 0
    pq = [(0, "A")]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    print("=== Shortest Paths from A ===")
