fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18925").expect("Failed to connect");
    stream.write_all(b"GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18925\r\nConnection: close\r\n\r\n").unwrap();
    stream.flush().unwrap();

    let mut response = Vec::new();
    stream.read_to_end(&mut response).unwrap();
    let response_str = String::from_utf8(response).unwrap();

    let body_start = response_str.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let body = &response_str[body_start..];

    let products = parse_products(body);

    let filtered: Vec<(String, f64)> = products
        .iter()
        .filter(|(_, price)| **price > 50.00)
        .map(|(name, price)| (name.clone(), *price))
        .collect();

    let mut sorted = filtered;
    sorted.sort_by(|a, b| a.0.cmp(&b.0));

    let total: f64 = sorted.iter().map(|(_, price)| *price).sum();
    let count = sorted.len();

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &sorted {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", count);
    println!("Total: ${:.2}", total);
}

