import * as fs from 'fs';

interface Graph {
  nodes: string[];
  edges: { from: string; to: string; weight: number }[];
}

function dijkstra(graph: Graph, start: string): Map<string, number> {
  const dist = new Map<string, number>();
  const visited = new Set<string>();

  for (const n of graph.nodes) {
    dist.set(n, Infinity);
  }
  dist.set(start, 0);

  const pq: { node: string; d: number }[] = [{ node: start, d: 0 }];

  while (pq.length > 0) {
    pq.sort((a, b) => a.d - b.d);
    const curr = pq.shift()!;

    if (visited.has(curr.node)) continue;
    visited.add(curr.node);

    const neighbors = graph.edges
      .filter(e => e.from === curr.node || e.to === curr.node)
      .map(e => e.from === curr.node ? e.to : e.from);

    for (const nb of neighbors) {
      const edge = graph.edges.find(e => 
        (e.from === curr.node && e.to === nb) || 
        (e.to === curr.node && e.from === nb)
      );
      if (!edge) continue;
      const newDist = curr.d + edge.weight;
      if (newDist < dist.get(nb)!) {
        dist.set(nb, newDist);
        pq.push({ node: nb, d: newDist });
      }
    }
  }

  return dist;
}

