static char *read_file(const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file: %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)size + 1);
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    size_t nread = fread(buf, 1, (size_t)size, f);
    buf[nread] = '\0';
    fclose(f);
    return buf;
}

static const char *skip_ws(const char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    return s;
}

static char *parse_json_string(const char **ptr) {
    *ptr = skip_ws(*ptr);
    if (**ptr != '"') return NULL;
    (*ptr)++;
    const char *start = *ptr;
    while (**ptr && **ptr != '"') {
        if (**ptr == '\\' && *(*ptr + 1)) (*ptr)++;
        (*ptr)++;
    }
    int len = (int)(*ptr - start);
    char *s = malloc((size_t)len + 1);
    if (!s) return NULL;
    memcpy(s, start, (size_t)len);
    s[len] = '\0';
    (*ptr)++;
    return s;
}

static int parse_json_int(const char **ptr) {
    *ptr = skip_ws(*ptr);
    int sign = 1;
    if (**ptr == '-') { sign = -1; (*ptr)++; }
    int val = 0;
    while (**ptr >= '0' && **ptr <= '9') {
        val = val * 10 + (**ptr - '0');
        (*ptr)++;
    }
    return val * sign;
}

