func multiply(_ M1: [[Int]], _ M2: [[Int]]) -> [[Int]] {
    let rows1 = M1.count
    let cols1 = M1[0].count
    let cols2 = M2[0].count

    var result = Array(repeating: Array(repeating: 0, count: cols2), count: rows1)

    for i in 0..<rows1 {
        for j in 0..<cols2 {
            var sum = 0
            for k in 0..<cols1 {
                sum += M1[i][k] * M2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ M: [[Int]]) -> Int {
    let a = M[0][0], b = M[0][1], c = M[0][2]
    let d = M[1][0], e = M[1][1], f = M[1][2]
    let g = M[2][0], h = M[2][1], i = M[2][2]

    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

func formatRow(_ row: [Int]) -> String {
    let padded = row.map { val -> String in
        let s = String(val)
        if s.count >= 4 { return s }
        return String(repeating: " ", count: 4 - s.count) + s
    }
    return "  " + padded.joined(separator: " ")
}

