        for (int j = 0; j < 3; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    printf("=== Matrix Operations ===\n");
    printf("\n");
    printf("Matrix A:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", A[i][0], A[i][1], A[i][2]);
    }
    printf("\n");

    printf("Matrix B:\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", B[i][0], B[i][1], B[i][2]);
    }
    printf("\n");

    printf("A x B =\n");
    for (int i = 0; i < 3; i++) {
        printf("  %4d %4d %4d\n", C[i][0], C[i][1], C[i][2]);
    }
    printf("\n");

    int det = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
            - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
            + C[0][2] * (C[1][0] * C[2][1] - C[1][1] * C[2][0]);

    printf("Determinant: %d\n", det);

    free(A);
    free(B);
    free(C);

    return 0;
}

fn main() {
